# Dump full source data cells C2:Z40 as JSON for filling
import openpyxl, json
src='/mnt/hhq/data/MiMotable/工程成本核算表1.xlsx'
wbs=openpyxl.load_workbook(src, data_only=True)
s=wbs['Sheet1']
out={}
for r in range(2,41):
    for c in range(3,27):
        v=s.cell(r,c).value
        if v is not None and not (isinstance(v,str) and v.startswith('=')):
            coord=openpyxl.utils.get_column_letter(c)+str(r)
            if isinstance(v,__import__('datetime').datetime):
                out[coord]={'type':'date','value':v.strftime('%Y-%m-%d %H:%M:%S')}
            else:
                out[coord]=v
print(len(out))
print(json.dumps(out, ensure_ascii=False, default=str))
